JSValue shader(const JSValue& node){auto value=node;for(unsigned i=0;i<16;++i){if(value.get("shaderNode").isObject())return value.get("shaderNode").get("jsFunc");value=value.get("node");if(!value.isObject())break;}throw std::logic_error("No real ModelNode Fn callback");}
