int main(int argc,char** argv){try{if(argc>1&&std::string(argv[1])=="--lifetime"){lifetime();return 0;}relative=argc>1&&std::string(argv[1])=="--relative-integration-node-ids";const std::string input(std::istreambuf_iterator<char>(std::cin),{});const auto requests=Animation_detail::parseJSON(input);auto out=array();for(unsigned i=0;i<requests.length();++i)call(out,"push",{run(requests.get(std::to_string(i)))});std::cout<<out.toJSON()->dump();}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
